compile.workshop:
variables {
    global:
        0: a
}

subroutines {
    0: retained
    1: unoptimized
}

rule ("macro passes around a relative jump") {
    event {
        Ongoing - Global;
    }
    actions {
        Skip(2);
        "pass"
        disabled Abort;
        Set Global Variable(a, 1);
        "pass"
        disabled Abort;
        Set Global Variable(a, 2);
    }
}

rule ("Subroutine retained") {
    event {
        Subroutine;
        retained;
    }
    actions {
        Skip(2);
        "pass"
        disabled Abort;
        Set Global Variable(a, 1);
        Set Global Variable(a, 2);
    }
}

//Optimizations disabled
rule ("macro pass in an unoptimized rule") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(a, 1);
        //Optimizations enabled
        "pass"
        disabled Abort;
        Set Global Variable(a, 2);
    }
}

//Optimizations disabled
rule ("Subroutine unoptimized") {
    event {
        Subroutine;
        unoptimized;
    }
    actions {
        "pass"
        disabled Abort;
        Set Global Variable(a, 1);
        Skip(2);
        "pass"
        disabled Abort;
        Set Global Variable(a, 2);
    }
}

